      "correct": "B",
      "answerText": "(B) Amygdala",
      "explanation": "The Amygdala is commonly called the “window of the limbic system” because it acts as a key center for interpreting emotional significance and linking emotions with behavior. The amygdala is an almond-shaped group of nuclei located deep in the medial temporal lobe of the brain and forms an important part of the Limbic system, which regulates emotions, motivation, and certain aspects of memory.\nThe amygdala receives sensory information from different areas of the brain, particularly through the Thalamus and cerebral cortex. It evaluates this information to determine its emotional importance, especially in situations involving fear, threat, or reward. Because it allows emotional responses to be expressed outwardly through autonomic and behavioral reactions, it is metaphorically referred to as the “window” through which the internal emotional activities of the limbic system are revealed.\nThe amygdala also interacts closely with other limbic structures such as the Hippocampus, helping to link emotional experiences with memories. Through these connections, it plays a crucial role in emotional learning, fear conditioning, and social behavior. Therefore, the correct answer is (B) Amygdala.",
