      "correct": "A",
      "answerText": "(A) Van den Bergh reaction",
      "explanation": "The classic laboratory method for measuring serum bilirubin levels is the Van den Bergh reaction. This reaction is based on the principle of the diazo reaction, first described by Ehrlich. It uses a diazo reagent (diazotized sulfanilic acid) which reacts with bilirubin to form a colored product called azobilirubin, which can be measured spectrophotometrically. A key aspect of the Van den Bergh test is its ability to differentiate between conjugated (direct) and unconjugated (indirect) bilirubin. Conjugated bilirubin is water-soluble and reacts directly with the diazo reagent, giving the direct bilirubin value. Unconjugated bilirubin, which is bound to albumin, requires the addition of an accelerator like alcohol or caffeine to react. The total bilirubin is measured after adding the accelerator, and the indirect bilirubin is calculated by subtracting the direct from the total value.",
