      "answerText": "(A) Km remains same, Vmax decreases",
      "explanation": "The question uses Michaelis-Menten kinetics terms (Km, Vmax) to describe a non-competitive antagonist, but these terms are for enzyme inhibitors. Assuming the question means a non-competitive inhibitor : a non-competitive inhibitor binds to the enzyme at a site distinct from the active site (an allosteric site). This binding can occur whether the substrate is bound or not. The inhibitor's binding changes the conformation of the enzyme, rendering it catalytically inactive. Because the inhibitor does not compete with the substrate for the active site, it does not affect the enzyme's affinity for the substrate, and therefore, the Km (Michaelis constant) remains the same. However, by inactivating a fraction of the enzyme molecules, the inhibitor effectively reduces the total concentration of functional enzyme available. This leads to a decrease in the Vmax (maximum reaction velocity), as the reaction can never reach the maximum velocity it would have in the absence of the inhibitor, no matter how much substrate is added.",
