      "explanation": "Dietary fiber is broadly classified into two categories based on its solubility in water : soluble and insoluble. Soluble fibers dissolve in water to form a viscous, gel-like substance in the digestive tract. This type of fiber is known to help lower blood cholesterol and glucose levels. Pectin, which is abundant in fruits like apples and citrus, is a primary example of a soluble fiber. Other examples include gums (like guar gum) and mucilages (found in psyllium). In contrast, insoluble fibers do not dissolve in water. They add bulk to the stool and promote regular bowel movements. Cellulose, hemicellulose, and lignin are the main types of insoluble fiber. They are the primary structural components of plant cell walls and are found in whole grains, nuts, and vegetables like cauliflower and green beans.",
