      "explanation": "The National Cholesterol Education Program Adult Treatment Panel III (NCEP-ATP III) defines the metabolic syndrome as the presence of three or more of five specific cardiometabolic risk factors. These five criteria are :\n1. Central Obesity : Defined as a waist circumference >102 cm (40 in) in men or >88 cm (35 in) in women.\n2. Hypertriglyceridemia : Defined as triglycerides ≥ 150 mg/dL or being on drug treatment for high triglycerides.\n3. Low HDL Cholesterol : Defined as HDL-C < 40 mg/dL in men or < 50 mg/dL in women.\n4. Hypertension : Defined as blood pressure ≥ 130/85 mmHg or being on drug treatment for hypertension.\n5. Elevated Fasting Glucose : Defined as fasting plasma glucose ≥ 100 mg/dL or being on drug treatment for hyperglycemia. Notably, a high level of LDL cholesterol is a major risk factor for cardiovascular disease on its own, but it is not one of the defining criteria for the metabolic syndrome according to the NCEP-ATP III guidelines.",
