      "correct": "C",
      "answerText": "(C) Metaplasia",
      "explanation": "The image depicts a change in the lining of a bronchus. The normal respiratory epithelium, which is ciliated pseudostratified columnar epithelium, is on the left. On the right, this has been replaced by a more rugged, stratified squamous epithelium. This reversible change of one differentiated cell type to another is known as metaplasia. In chronic smokers, the constant irritation from the smoke causes the delicate ciliated columnar cells of the bronchial lining to be replaced by the more robust stratified squamous cells, which are better able to withstand the chemical insult. While this squamous metaplasia is initially a protective adaptation, it is not a normal state. The new epithelium lacks cilia and mucus-secreting goblet cells, impairing the mucociliary clearance mechanism. Importantly, this metaplastic tissue is fertile ground for the future development of dysplasia and, eventually, squamous cell carcinoma if the irritation continues.",
