      "number": 58,
      "statement": "A 51-year-old individual presents with hematuria. On examination, the patient is normotensive and has pedal edema. Investigations show absence of glucosuria and an elevated serum creatinine level of 9 mg%. Renal biopsy findings are shown below. Which of the following investigations should be performed to determine the underlying etiology of this condition?",
