      "correct": "C",
      "answerText": "(C) Alpha-1 antitrypsin deficiency",
      "explanation": "The patient is a 35-year-old woman with chronic dyspnea, productive cough, and wheezing, who eventually died from respiratory failure. Importantly, she has no history of smoking, which suggests a genetic cause of emphysema rather than smoking-related COPD.\nThe lung pathology image shows marked enlargement of air spaces with destruction of alveolar walls, characteristic of emphysema. In young non-smokers, the most likely cause of emphysema is alpha-1 antitrypsin (AAT) deficiency.\nAlpha-1 antitrypsin is a protease inhibitor produced in the liver that normally inhibits neutrophil elastase. When AAT is deficient, unopposed elastase activity destroys elastic tissue in the lungs, leading to panacinar emphysema, typically affecting the lower lobes.\nWhy the other options are incorrect:\n1. Mutation in dynein arms: Causes primary ciliary dyskinesia (Kartagener syndrome) with recurrent infections and bronchiectasis.\n2. Cystic fibrosis: Causes thick mucus and bronchiectasis, not classic emphysema.\n3. Antibodies against type IV collagen: Seen in Goodpasture syndrome, affecting lungs and kidneys.\nThus, the underlying condition responsible for these lung changes is alpha-1 antitrypsin deficiency.",
