      "answerText": "(D) Adenosine A1 receptor antagonism",
      "explanation": "Theophylline, a methylxanthine, is primarily used as a bronchodilator for asthma and COPD. One of its well-known side effects is a mild diuretic action. While theophylline is a non-selective phosphodiesterase (PDE) inhibitor, its diuretic effect is not primarily mediated by this action. The main mechanism behind its diuretic property is the antagonism of adenosine A1 receptors in the kidneys. Adenosine, acting on A1 receptors in the afferent arterioles of the glomerulus, causes vasoconstriction and a decrease in the glomerular filtration rate (GFR). By blocking these receptors, theophylline opposes the action of adenosine, leading to afferent arteriole vasodilation, an increase in renal blood flow and GFR, and consequently, an increase in urine output (diuresis). It also inhibits sodium reabsorption in the proximal tubules, further contributing to the diuretic effect. PDE inhibition contributes more to its bronchodilator and cardiac effects.",
