      "number": 84,
      "statement": "Zero-order (saturation) kinetics is independent of which of the following factors?",
      "options": [
        "Plasma concentration",
        "Clearance",
        "Volume of distribution",
        "Half life"
      ],
      "correct": "A",
      "answerText": "(A) Plasma concentration",
      "explanation": "Drug elimination can follow either first-order or zero-order kinetics. In zero-order kinetics, the rate of elimination is constant and is independent of the drug's plasma concentration. This occurs when the metabolic or elimination pathways are saturated. A constant amount of the drug is eliminated per unit of time, regardless of how much drug is in the body. Classic examples include ethanol, phenytoin, and aspirin at high doses. In contrast, in first-order kinetics (which most drugs follow at therapeutic doses), a constant fraction of the drug is eliminated per unit of time, and the rate of elimination is directly proportional to the plasma concentration. In zero-order kinetics, concepts like a constant half-life and clearance are no longer valid, as they change with the plasma concentration.",
