      "explanation": "In cases of civil medical negligence, the legal principle of onus probandi, or the burden of proof, rests squarely on the claimant or plaintiff, which in this context is the patient (or their relatives). The patient who alleges negligence must prove their case to the court on a balance of probabilities. This involves establishing the four essential elements of negligence :\n1. Duty : That the doctor owed a duty of care to the patient.\n2. Dereliction : That the doctor breached this duty by failing to provide a standard of care that a reasonably prudent doctor would have provided in similar circumstances.\n3. Direct Causation : That this breach of duty was the direct cause of the harm or injury suffered by the patient.\n4. Damages : That the patient suffered quantifiable harm as a result.\nThe doctor (defendant) does not have to prove their innocence; rather, the patient must prove the doctor's liability.",
