      "explanation": "Tattoos are created by injecting insoluble ink pigments into the dermis layer of the skin. Over time, some of these pigment particles are engulfed by macrophages and transported via the lymphatic system to the regional lymph nodes, where they are deposited and stored permanently. This process, known as lymphatic drainage, is a normal physiological response. In a deceased person, especially if the skin is decomposed, burned, or obscured, the tattoo itself may become invisible. However, the pigment will still be present within the regional draining lymph nodes. Therefore, during a postmortem examination, the forensic pathologist can dissect and examine the regional lymph nodes corresponding to the alleged tattoo location. Finding the characteristic ink pigment within these nodes can serve as a definitive method of identification, confirming the presence of a tattoo even when it is no longer visible on the skin surface.",
