      "explanation": "A common misconception is that the hymen will always tear during sexual penetration. However, in prepubertal children, the hymen is typically highly elastic and redundant. It is rich in estrogen receptors, and in the low-estrogen prepubertal state, it is often thicker and more flexible compared to the hymen of an adolescent or adult. Because of this high elasticity, the hymen in a young child can often stretch to accommodate a penetrating object, including a finger or even an erect penis, without tearing. Therefore, the absence of a hymenal tear is not evidence that sexual abuse has not occurred. Forensic examination must look for other, more subtle signs of injury, such as abrasions, erythema, or posterior fourchette tears. The statement that the hymen hardly tears because it is highly elastic is the most forensically accurate option.",
