      "correct": "A",
      "answerText": "(A) Cocaine poisoning",
      "explanation": "Magnan's sign or symptom is a specific type of tactile hallucination that is classically associated with chronic cocaine abuse. It is a form of formication, which is the sensation of insects crawling on or under the skin. Individuals experiencing this symptom may have a delusional belief that they are infested with parasites (delusional parasitosis). This can lead them to compulsively pick at, scratch, or excoriate their skin in an attempt to remove the imaginary cocaine bugs, resulting in characteristic skin lesions. While formication can occur with other stimulant abuse (like amphetamines) or in alcohol withdrawal, its specific association with the sensation of bugs crawling under the skin is classically known as Magnan's sign of cocaine toxicity.",
