      "explanation": "Donovanosis, also known as granuloma inguinale, is a chronic, progressive ulcerative sexually transmitted infection. The causative agent is Klebsiella granulomatis (formerly known as Calymmatobacterium granulomatis). This is a Gram-negative intracellular bacterium. The diagnosis is typically made by microscopic examination of a crush preparation or biopsy from the lesion, stained with Giemsa or Wright stain. The pathognomonic finding is the presence of Donovan bodies, which are clusters of the small, encapsulated bacterial coccobacilli seen within the cytoplasm of large mononuclear cells (macrophages). The disease presents as painless, beefy-red, friable ulcers that progressively expand. H. ducreyi (A) causes chancroid, L. donovani (B) causes leishmaniasis, and T. pallidum (D) causes syphilis.",
