      "explanation": "Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii, is the classic example of a fungal infection acquired via traumatic inoculation. This fungus lives in soil, sphagnum moss, and on plants. The infection typically occurs when the contaminated plant material (like a rose thorn, hence the name rose gardener's disease) causes a small cut or puncture wound in the skin, directly inoculating the fungus into the subcutaneous tissue. This results in the formation of a small, painless nodule at the site of inoculation, which may ulcerate. The infection then classically spreads along the lymphatic channels, forming a chain of secondary nodules and ulcers known as lymphogenous sporotrichosis. In contrast, the other fungi listed (Blastomycosis, Coccidioidomycosis, and Para coccidioidomycosis) are systemic mycoses that are primarily acquired by inhalation of airborne spores into the lungs.",
