      "correct": "C",
      "answerText": "(C) IL 4",
      "explanation": "The process of isotype switching in B-lymphocytes, where they switch from producing IgM to other antibody classes like IgG, IgA, or IgE, is directed by specific cytokines produced by T-helper cells. The key cytokine responsible for inducing B-cells to switch to the production of Immunoglobulin E (IgE) is Interleukin-4 (IL-4). IL-4, along with IL-13, is a signature cytokine of the Th2 immune response, which is central to allergic reactions and the defense against helminthic parasites. IL-4 signals B-cells to undergo class switch recombination at the immunoglobulin heavy chain locus, leading to the expression of the epsilon heavy chain and the secretion of IgE. IL-5, another Th2 cytokine, is important for the activation of eosinophils, which are often involved in IgE-mediated responses. IL-1 is a pro-inflammatory cytokine, and IL-3 is a hematopoietic growth factor.",
