      "explanation": "According to India's Bio-Medical Waste Management Rules, different categories of waste are segregated into color-coded containers for appropriate treatment and disposal. Chemical waste, which includes discarded chemicals used in disinfection, laboratory reagents, and expired or discarded disinfectants, falls into the Yellow category. This category is broad and also includes human anatomical waste, soiled waste, and expired medicines. Specifically, liquid chemical waste should be pre-treated (if required) and then sent for disposal in the yellow stream, typically to a secure landfill or for incineration depending on its nature. It should not be mixed with recyclable plastics (Red), glass (Blue), or sharps (White/Translucent). Proper segregation ensures that hazardous chemicals are handled safely and do not contaminate other waste streams or the environment.",
