      "number": 125,
      "statement": "A study follows a normal distribution with a median of 200 and a standard deviation of 20. Between which values will approximately 68% of the observations lie?",
      "options": [
        "160-240",
        "170-230",
        "180-220",
        "190-210"
      ],
