      "answerText": "(C) 180-220",
      "explanation": "This question refers to the empirical rule of a normal distribution. In a normal distribution, the mean, median, and mode are all equal. Therefore, the mean of this distribution is 200. The empirical rule states that for a normal distribution, specific percentages of the data fall within certain ranges of standard deviations (SD) from the mean (μ). Specifically, approximately 68% of all values lie within one standard deviation of the mean (μ ± 1 SD). Given : Mean (μ) = 200 Standard Deviation (σ) = 20 To find the range for 68% of the values, we calculate : Lower limit = μ - 1σ = 200 - 20 = 180 Upper limit = μ + 1σ = 200 + 20 = 220 Thus, 68% of the values will fall between the range of 180 and 220. The range 160-240 (A) would represent approximately 95% of the values (μ ± 2 SD).",
