      "explanation": "The World Health Organization (WHO) provides Medical Eligibility Criteria for contraceptive use. For Intrauterine Devices (IUDs), there are several absolute contra indications (Category 4), where the risk is unacceptable. These include suspected or confirmed pregnancy, current pelvic inflammatory disease (PID) or a high risk of STIs, and unexplained or undiagnosed abnormal vaginal bleeding, as this could be a sign of an underlying malignancy. A uterine malformation (such as a bicornuate or septate uterus) that significantly distorts the uterine cavity is also a contraindication. However, this is often considered a relative contraindication (Category 3 or 4 depending on severity), as the IUD may not fit properly, leading to a higher risk of expulsion or perforation. Compared to active pregnancy or PID, which are absolute contra indications, a uterine anomaly's contraindication can be more nuanced, making it the most likely answer for not an absolute contraindication in all cases.",
