      "statement": "Admission rate bias is classified under which type of bias?",
      "options": [
        "Reporting bias",
        "Response bias",
        "Berkesonian bias",
        "None"
      ],
      "correct": "C",
      "answerText": "(C) Berkesonian bias",
      "explanation": "Berksonian bias, also known as admission rate bias, is a specific type of selection bias that can occur in case-control studies that are conducted in a hospital setting. This bias arises because the combination of a particular exposure and a specific disease may increase the likelihood of a person being admitted to the hospital. This can lead to a spurious association between the exposure and the disease in the hospital-based study population that does not exist in the general population. For example, if both smoking and chronic bronchitis independently increase the likelihood of hospitalization, a hospital-based case-control study of another disease (e.g., peptic ulcer) might find a false association with smoking because smokers with bronchitis are overrepresented in the hospital population. This distortion of the exposure-disease relationship due to differential hospital admission rates is the essence of Berksonian bias.",
