      "explanation": "The phenomenon where stimulation of the external auditory canal triggers a cough is known as Arnold's reflex or the ear-cough reflex. This reflex is mediated by the auricular branch of the vagus nerve (cranial nerve X), also known as Arnold's nerve. This small sensory nerve supplies the skin of the concha and the posterior part of the external auditory meatus. The vagus nerve is the primary afferent and efferent pathway for the cough reflex originating from the larynx and tracheobronchial tree. Because the auricular branch is part of this same cranial nerve, direct mechanical stimulation (e.g., by an otoscope or a cotton swab) of the ear canal can aberrantly trigger the vagal cough reflex arc in the brainstem, causing a person to cough even though there is no irritation in their airway. This is a classic example of a referred reflex.",
