      "explanation": "Tuberculous otitis media is a rare form of chronic suppurative otitis media caused by Mycobacterium tuberculosis. It has several classic clinical features that distinguish it from the more common pyogenic forms. One of its most defining characteristics is a painless, profuse, and persistent otorrhea (ear discharge). The lack of pain, despite significant tissue destruction, is a major clinical clue. Other classic findings include the presence of multiple perforations of the tympanic membrane which may later coalesce, pale and sluggish granulations in the middle ear cleft, and severe destruction of the ossicular chain, leading to a significant conductive hearing loss. Facial nerve palsy is also more common than in typical otitis media. Therefore, painful otorrhea is the feature that is not characteristic; the discharge is classically described as painless.",
