      "answerText": "(A) Exudative Retinal Detachment",
      "explanation": "Exudative (or serous) retinal detachment is a type of retinal detachment that occurs without a retinal break or tear. Instead, it is caused by the accumulation of fluid in the subretinal space due to the breakdown of the blood-retinal barrier. This fluid leaks from the retinal or choroidal vessels, a process often driven by underlying inflammation, tumors, or vascular abnormalities. A hallmark clinical sign of an exudative detachment is shifting fluid. Because the subretinal fluid is not contained by fibrous membranes and is subject to gravity, its position and the location of the retinal detachment will change depending on the patient's head position. For example, the fluid may pool inferiorly when the patient is upright and then shift to the macula when they lie down. This phenomenon is not seen in tractional detachments, which are fixed, or rhegmatogenous detachments, where fluid is more localized around a break.",
