      "answerText": "(C) Optic tract",
      "explanation": "A lesion of the optic tract produces a contralateral homonymous hemianopia. Because the fibers from corresponding retinal points are not yet perfectly aligned in the optic tract, the visual field defects in each eye are typically incongruous (not identical in shape and size). Furthermore, the optic tract contains pupillary afferent fibers that are traveling towards the pretectal nucleus. A lesion in the optic tract will interrupt these fibers. This can be detected by the Wernicke's hemianopic pupil sign : when a slit of light is shone on the blind half of the retina, the pupil does not constrict, but when it is shone on the seeing half, the pupillary light reflex is normal. This sign specifically localizes the lesion to a pre-geniculate level, i.e., the optic tract. Lesions in the optic radiation or cortex are post-geniculate; they cause congruous hemianopias and do not affect the pupillary light reflex.",
