      "answerText": "(A) Penetrating injury to the eye",
      "explanation": "Sympathetic ophthalmia is a rare, devastating, bilateral granulomatous panuveitis that occurs after trauma to one eye. The essential prerequisite for this condition is a penetrating (or perforating) injury to one eye, which is then called the exciting eye. The injury exposes intraocular antigens (such as retinal S-antigen) to the systemic immune system, which are normally sequestered and recognized as self. This breaks immune tolerance and triggers a delayed-type (Type IV) hypersensitivity reaction. This autoimmune response then attacks not only the injured eye but also the uninjured, contralateral sympathizing eye, leading to bilateral severe inflammation and potential blindness. The condition almost never occurs after blunt trauma or chemical injury unless there is an associated globe rupture. Prompt enucleation (removal) of a severely injured, blind eye can prevent the development of sympathetic ophthalmia.",
