      "answerText": "(B) Macula and optic nerve diseases",
      "explanation": "The photostress recovery test is a simple clinical test used to differentiate between vision loss caused by macular disease and vision loss caused by optic nerve disease. The test involves first measuring the patient's best-corrected visual acuity in the affected eye. Then, a bright light (like from an ophthalmoscope) is shone into the eye for 10 seconds to bleach the photoreceptors. The light is then removed, and the time it takes for the patient's visual acuity to return to within one line of the pre-test level is measured. In a normal eye, recovery takes less than 60 seconds. In an eye with macular disease, the recovery of the bleached photoreceptors is significantly delayed, and the recovery time will be prolonged (often >90 seconds). In an eye with optic nerve disease, the photoreceptors are healthy, and the recovery time will be normal.",
