      "explanation": "Esotropia is a type of strabismus where one or both eyes turn inward, toward the nose. There is a strong association between accommodative esotropia and hypermetropia (farsightedness). This relationship is based on the synkinesis (linked movement) between accommodation and convergence. A hypermetropic eye must accommodate (increase the focusing power of its lens) to see clearly, both at distance and especially at near. This effort of accommodation is reflexively linked to an effort of convergence (turning the eyes inward). In a child with a significant amount of uncorrected hypermetropia, the excessive and constant accommodative effort required to maintain clear vision leads to an over-convergence of the eyes, resulting in the development of esotropia. This is why the initial treatment for accommodative esotropia is the full correction of the underlying hypermetropic refractive error with glasses.",
