      "correct": "A",
      "answerText": "(A) Latanoprost",
      "explanation": "The management of glaucoma (characterized by increased IOP and optic disc changes) involves lowering the IOP. This can be achieved by either decreasing the production of aqueous humor or increasing its outflow from the eye. There are two main outflow pathways : the conventional trabecular meshwork pathway and the unconventional uveoscleral pathway. Prostaglandin analogs, such as Latanoprost, are a first-line class of medications for glaucoma that work primarily by increasing the outflow of aqueous humor through the uveoscleral pathway. They do this by relaxing the ciliary muscle and remodeling the extracellular matrix in the uveoscleral space, which reduces resistance to outflow. Pilocarpine (B) increases outflow through the trabecular meshwork. Timolol (D, a beta-blocker) and dorzolamide (C, a carbonic anhydrase inhibitor) work by decreasing the production of aqueous humor.",
