      "explanation": "Several medications used to treat rheumatoid arthritis can have ocular side effects. One of the most well-known toxicities is associated with the antimalarial drugs chloroquine and hydroxy chloroquine. While the most feared complication is an irreversible bull's-eye maculopathy, these drugs can also affect the cornea. A characteristic finding is cornea verticillata (also known as vortex keratopathy), which is the deposition of the drug in the corneal epithelium. This creates fine, greyish or golden-brown opacities that swirl outwards from a point below the pupil in a whorl-like pattern. While often asymptomatic, these corneal opacities can sometimes cause blurred vision, glare, and halos around lights. The development of corneal opacities in a patient on long-term treatment for RA is highly suggestive of chloroquine or hydroxy chloroquine keratoplasty.",
