      "explanation": "Nutcracker esophagus, also known as hypertensive peristalsis, is a motility disorder of the esophagus. It is defined by manometric findings of normal, coordinated peristalsis in the esophageal body, but with extremely high-amplitude or long-duration contractions. The peristaltic waves are normally sequenced but are simply too powerful. This hyper contractility is thought to be the cause of the primary symptoms, which are non-cardiac chest pain and dysphagia (difficulty swallowing). The diagnosis is made exclusively by high-resolution esophageal manometry, which will show distal contractile integral (DCI) values greater than 8,000 mmHg·s·cm. It is a benign motility disorder, not a malignancy (C is incorrect). Medical treatments, though often of limited efficacy, are available and include calcium channel blockers, nitrates, and proton pump inhibitors (B is incorrect).",
