      "correct": "B",
      "answerText": "(B) Meningo-encephalitis",
      "explanation": "While pneumonia is the most common cause of death from measles and otitis media is the most frequent complication overall, the most serious and devastating complication is acute meningoencephalitis. This neurological complication occurs in approximately 1 in 1,000 cases of measles, typically appearing a few days after the onset of the rash. It can manifest with seizures, altered consciousness, and focal neurological deficits. The mortality rate from measles encephalitis is high (around 15%), and a significant proportion of survivors (25-40%) are left with permanent neurological sequelae, including intellectual disability, seizure disorders, deafness, and motor impairments. Another even more devastating, though much rarer, neurological complication is Subacute Sclerosing Panencephalitis (SSPE), a progressive and universally fatal disease that develops years after the initial infection. Due to the high risk of both death and severe, lifelong disability, encephalitis is considered the most serious complication of acute measles infection.",
