      "answerText": "(A) Lupus nephritis",
      "explanation": "Systemic Lupus Erythematosus (SLE) is a multisystem autoimmune disease that can have severe manifestations in children. While modern treatments have significantly improved survival, mortality is still a concern. The most common cause of death in children with SLE has historically been related to end-organ damage from the disease itself, and the most frequently and severely affected organ is the kidney. Lupus nephritis, which is the inflammation of the kidneys caused by the deposition of immune complexes, is a major cause of morbidity and mortality. It can progress to end-stage renal disease (ESRD), requiring dialysis or transplantation. While infections (D), often related to the immunosuppressive therapies used to treat SLE, have emerged as a leading cause of death in recent years, renal failure from uncontrolled lupus nephritis remains a primary and classic cause of mortality in this population. Lupus cerebritis (B) and cardiac complications (C) are also serious but are less common causes of death than renal disease.",
