      "number": 194,
      "statement": "A patient presents with the following arterial blood gas (ABG) and electrolyte values : pH=7.24 pO₂=80 mmHg, PaCO₂=36 mmHg, HCO₃⁻=14 mmol/L, Na⁺=131 mmol/L, Cl⁻=90 mmol/L, Base excess (BE)=-13, Glucose =135 mg/dL. What is the most likely acid-base disturbance?",
