      "explanation": "To interpret the ABG, we follow a systematic approach :\n1. Check the pH : The pH is 7.24, which is less than the normal range (7.35-7.45). This indicates an acidosis.\n2. Check the PaCO₂ : The PaCO₂ is 36 mmHg, which is within the normal range (35-45 mmHg). This suggests the primary problem is not respiratory. The PaCO₂ is slightly on the low side of normal, indicating some minor respiratory compensation may be starting.\n3. Check the HCO₃⁻ : The bicarbonate level is 14 mmol/L, which is significantly lower than the normal range (22-28 mmol/L). A low bicarbonate level is the defining feature of a metabolic acidosis.\nThe combination of a low pH and a low HCO₃⁻ confirms a primary metabolic acidosis. We can also calculate the anion gap : AG = Na⁺ - (Cl⁻ + HCO₃⁻) = 131 - (90 + 14) = 131 - 104 = 27. This is a high anion gap metabolic acidosis.",
