      "number": 197,
      "statement": "What feature best distinguishes irritable bowel syndrome (IBS) from organic gastrointestinal disease?",
      "options": [
        "Diarrhea",
        "Stool calprotectin",
        "Abdominal pain",
        "Mucus in stools"
      ],
      "correct": "B",
      "answerText": "(B) Stool calprotectin",
      "explanation": "Irritable Bowel Syndrome (IBS) is a functional gastrointestinal disorder, meaning it is characterized by symptoms without any visible or structural organic disease. Its symptoms, such as abdominal pain, diarrhea, and mucus in the stools, can significantly overlap with those of organic diseases like Inflammatory Bowel Disease (IBD - Crohn's disease and ulcerative colitis). A key challenge is to differentiate between these conditions. Fecal calprotectin is an excellent non-invasive biomarker for this purpose. Calprotectin is a protein released by neutrophils. Its presence in the stool indicates neutrophilic inflammation in the intestinal mucosa. In organic inflammatory diseases like IBD, there is significant inflammation, leading to a high fecal calprotectin level. In contrast, IBS is a non-inflammatory condition, so the fecal calprotectin level will be normal. This makes it a highly useful test to differentiate the functional symptoms of IBS from the inflammatory symptoms of organic GI disease.",
