      "correct": "B",
      "answerText": "(B) 42°C.",
      "explanation": "Standard medical protocol for frostbite is rapid rewarming of the affected area in a controlled water bath. The goal is to thaw the frozen tissue quickly without causing additional thermal injury.\nThe recommended water temperature is between 37°C and 42°C (98.6°F to 107.6°F). This range is optimal because it's warm enough to restore circulation and thaw tissue efficiently, yet safely below the temperature that would burn the skin. Because the frostbitten area is numb, the individual cannot feel pain, making them highly susceptible to burns from water that is too hot.\nTemperatures like 44°C or 46°C are dangerously high and can cause severe burns, worsening the injury. Rewarming is typically continued for 15–30 minutes until the skin becomes red and soft. This process is often extremely painful as sensation returns, requiring medical supervision and pain management.",
