      "correct": "A",
      "answerText": "(A) Posterior Inferior Cerebellar Artery (PICA)",
      "explanation": "This pattern of crossed sensory loss is the hallmark of Wallenberg syndrome, also known as the lateral medullary syndrome. This syndrome is caused by an infarct in the dorsolateral medulla of the brainstem. The artery most commonly occluded to cause this syndrome is the vertebral artery, followed by its branch, the Posterior Inferior Cerebellar Artery (PICA). The infarct damages several key structures in this region. Specifically, it affects the spinal trigeminal nucleus, which receives pain and temperature sensation from the ipsilateral face, causing loss of sensation there. It also damages the spinothalamic tract, which carries pain and temperature sensation from the contralateral side of the body, causing a loss of sensation on the opposite side. This crossed pattern is highly specific for a lesion in the lateral medulla.",
