      "explanation": "The patient's clinical signs—respiratory distress, hypotension, unilateral absent breath sounds, and subcutaneous emphysema following trauma—are classic for a tension pneumothorax. This is a life-threatening emergency that causes obstructive shock and requires immediate intervention to relieve the pressure in the chest. The definitive immediate management is needle decompression (thoracostomy). The most recent Advanced Trauma Life Support (ATLS) guidelines recommend inserting a large-bore needle into the 5th intercostal space in the anterior or mid-axillary line. This site is preferred over the traditional 2nd intercostal space in the mid-clavicular line because the chest wall is thinner here, reducing the risk of the needle not reaching the pleural space. This procedure converts the tension pneumothorax into a simple pneumothorax, which should then be followed by the insertion of a formal chest tube. Fluid resuscitation is also important, but relieving the tension physiology is the first priority.",
