      "correct": "B",
      "answerText": "(B) Induration",
      "explanation": "The ASEPSIS score is a validated wound scoring system used to assess and quantify the severity of a surgical site infection (SSI). It assigns points based on both clinical findings observed during the postoperative period and the need for additional treatment. The clinical criteria scored as part of the ASEPSIS system include :\n1. The presence of serous discharge.\n2. The presence of erythema (redness).\n3. The presence of purulent exudate (pus).\n4. The separation of the deep tissues.\nAdditional points are given if the patient requires antibiotic treatment for the wound infection or requires drainage of pus under local or general anesthesia. The system also considers the results of microbiological culture from the wound. Induration (hardening of the tissue) is a common sign of inflammation and infection but is not a specific, scored component of the ASEPSIS scoring system itself.",
