      "explanation": "The risk of specific opportunistic infections after solid organ transplantation follows a typical timeline based on the patient's net state of immunosuppression. The period from 1 to 6 months post-transplant is the time of maximal immunosuppression and is when opportunistic viral infections are most common. Cytomegalovirus (CMV) is the single most important and frequent pathogen during this window. CMV infection can arise from reactivation of latent virus in the recipient, or more commonly, as a primary infection from a CMV-positive donor organ transplanted into a CMV-negative recipient. It can cause a wide spectrum of disease, from a mononucleosis-like syndrome to invasive tissue disease affecting the lungs, GI tract, and the allograft itself. Fungal infections like Candida and Aspergillus typically occur in the first month, while late infections (>6 months) are more often community-acquired pathogens or related to PTLD (driven by EBV).",
