      "explanation": "Pancreatic neuroendocrine tumors (PNETs) are rare tumors that can be functional (hormone-secreting) or non-functional. Among the functional PNETs, the most common type is the insulinoma. Insulinomas are tumors of the pancreatic beta cells that autonomously secrete excessive amounts of insulin. This leads to inappropriate hyperinsulinemia, which causes recurrent episodes of hypoglycemia, particularly during fasting or after exercise. The clinical presentation is characterized by Whipple's triad : symptoms of hypoglycemia (e.g., confusion, sweating, palpitations), a documented low plasma glucose level during the episode, and relief of symptoms upon administration of glucose. The vast majority (>90%) of insulinomas are benign and solitary. Gastrinomas are the second most common functional PNET, but they are more often located in the duodenum than the pancreas itself.",
