      "number": 238,
      "statement": "Which parameter conclusively rules out malnutrition?",
      "options": [
        "Edema",
        "Lean body mass",
        "Skinfold thickness",
        "Normal ECF volume"
      ],
      "correct": "B",
      "answerText": "(B) Lean body mass",
      "explanation": "Assessment of malnutrition involves evaluating body composition, anthropometric measurements, and clinical signs. Among the available parameters, lean body mass (LBM) is the most reliable indicator for ruling out malnutrition.\nLean body mass represents the weight of all body components excluding fat, including muscles, bones, organs, and body water. Since protein-energy malnutrition primarily causes loss of muscle mass, a normal lean body mass strongly suggests adequate nutritional status, thereby helping to rule out malnutrition.\nThe other options are less reliable:\n1. Edema : Edema may occur in severe malnutrition such as kwashiorkor, but its absence does not exclude malnutrition.\n2. Skinfold thickness : This measures subcutaneous fat stores, which may vary with age, sex, and body type and does not directly reflect protein status.\n3. Normal extracellular fluid (ECF) volume : Fluid balance may remain normal even in malnourished individuals, so it cannot rule out malnutrition.\nTherefore, normal lean body mass is the parameter that most conclusively rules out malnutrition.",
