      "correct": "C",
      "answerText": "(C) TOF (Tetralogy of Fallot)",
      "explanation": "The chest X-ray shows a characteristic “boot-shaped heart” (coeur en sabot). This appearance occurs due to right ventricular hypertrophy, which elevates the cardiac apex and gives the heart a boot-like configuration. Additionally, there is decreased pulmonary vascular markings (pulmonary oligemia) because of reduced pulmonary blood flow.\nTetralogy of Fallot is a congenital cyanotic heart disease consisting of four components:\n1. Ventricular septal defect (VSD)\n2. Pulmonary stenosis\n3. Right ventricular hypertrophy\n4. Overriding aorta\nThe right ventricular hypertrophy produces the typical boot-shaped cardiac silhouette seen on the X-ray.\nWhy other options are incorrect:\n1. Transposition of the Great Arteries (TGA): Shows an “egg on a string” appearance.\n2. Total Anomalous Pulmonary Venous Connection (TAPVC): Shows a “snowman” or “figure-of-eight” sign in supra cardiac type.\n3. Ebstein’s anomaly: Shows massive cardiomegaly with a box-shaped heart.\nThus, the radiographic appearance in the image is most consistent with Tetralogy of Fallot.",
