      "answerText": "(B) Rheumatoid arthritis",
      "explanation": "The image shows a swan neck deformity of the finger. This deformity is characterized by hyperextension of the proximal interphalangeal (PIP) joint and compensatory flexion of the distal interphalangeal (DIP) joint. A swan neck deformity is a classic finding in Rheumatoid Arthritis (RA). It is caused by chronic inflammation and synovitis of the PIP joint, which stretches and damages the volar plate (the ligament that prevents hyperextension). This allows the extensor mechanism to pull the PIP joint into hyperextension. The altered tendon mechanics then cause the DIP joint to be pulled into flexion. The characteristic pattern of joint involvement in RA includes the wrists, metacarpophalangeal (MCP), and PIP joints, while typically sparing the DIP joints from primary inflammation, which aligns with the question's description. Osteoarthritis, in contrast, classically affects the DIP joints (Heberden's nodes).",
