      "correct": "A",
      "answerText": "(A) Cobb's angle",
      "explanation": "The image displays an anteroposterior radiograph of the spine showing a lateral curvature, which is scoliosis. The lines and angle drawn on the X-ray represent the standard method for measuring the magnitude of this curvature. This measurement is known as the Cobb angle. To measure the Cobb angle, one first identifies the most tilted vertebrae at the top and bottom of the curve (the end vertebrae). A line is then drawn along the superior endplate of the upper end vertebra, and another line is drawn along the inferior endplate of the lower end vertebra. The angle formed by the intersection of lines drawn perpendicular to these two lines is the Cobb angle. It is the universally accepted standard for quantifying the severity of scoliosis and for monitoring its progression.",
