      "answerText": "(D) Repair 3 months post-delivery",
      "explanation": "A complete perineal tear (third or fourth-degree) is a significant obstetric injury involving the anal sphincter complex. The ideal management is primary repair immediately after delivery. However, when a patient presents with a missed or broken-down repair two weeks after delivery, immediate re-repair is contraindicated. At this stage, the tissues are edematous, friable, and often infected, making a successful repair very unlikely to heal properly. The standard approach in this situation is a delayed secondary repair. The wound is managed with local care, sitz baths, and antibiotics if needed, and the patient is allowed to heal by secondary intention. The definitive surgical repair is then performed after a period of at least 3 months postpartum. This delay allows the inflammation to completely subside, the tissues to become supple and well-vascularized, and the scar to mature, which provides the best possible conditions for a successful and durable surgical reconstruction of the perineal body and anal sphincter.",
