      "explanation": "This is a classic presentation of an imperforate hymen. The patient has normal ovarian function, leading to regular hormonal cycles and menstrual bleeding. However, the imperforate hymen acts as a complete obstruction at the vaginal outlet. This causes the menstrual blood to become trapped and accumulate in the vagina, a condition known as hematocolpos. As more blood collects with each cycle, the uterus may also fill with blood (hematometra). This accumulation is responsible for the cyclic, crampy lower abdominal pain that mimics menstrual cramps but with no bleeding. The collection of blood distends the uterus and vagina, creating the palpable midline abdominal swelling (the enlarged uterus) and the bulging mass in the vagina that can be felt on rectal examination. The primary amenorrhea is simply because the blood has no way to exit. This set of findings is pathognomonic.",
