      "explanation": "Puberty in females is driven by hormones from both the ovaries (estrogen) and the adrenal glands (androgens). Estrogen is responsible for the development of most female secondary sexual characteristics. It stimulates breast development (thelarche), growth of the uterus, cornification of the vaginal epithelium, and the production of thin, watery cervical mucus. The cyclical withdrawal of estrogen and progesterone is what leads to menstruation (menarche). In contrast, the growth of pubic and axillary hair (pubarche or adrenarche) is an androgen-dependent process. These androgens are primarily produced by the adrenal glands. Therefore, hair growth is not directly dependent on estrogen and is mediated by a different hormonal pathway during puberty.",
