      "answerText": "(A) Meconium peritonitis",
      "explanation": "This question describes a neonate, not the mother. The history of meconium-stained liquor suggests fetal distress and is a risk factor for meconium-related complications. Meconium peritonitis is a sterile, chemical peritonitis that results from a perforation of the intestine in utero. The perforation allows sterile meconium to leak into the peritoneal cavity, where it elicits an intense inflammatory response. This can lead to the formation of ascites, calcifications, and the development of meconium pseudocysts. After birth, the infant may present with signs of intestinal obstruction, such as abdominal distension, vomiting, and failure to pass meconium. An ultrasound showing edematous bowel loops, ascites, and possibly intra-abdominal calcifications would be consistent with this diagnosis. The other options are general post-operative complications, but meconium peritonitis is a specific neonatal condition linked to the history.",
