      "explanation": "This question tests fundamental principles of radiobiology and physics. The correct statement is an expression of the Inverse Square Law, a key principle in physics. It states that the intensity of a physical quantity like radiation emanating from a point source is inversely proportional to the square of the distance from that source. This means if you double the distance from a radiation source, the dose you receive will decrease by a factor of four (1/2²). This law is critical in radiotherapy for calculating tumor and normal tissue doses and for radiation protection. The other statements are false. According to the Law of Bergonié and Tribondeau, rapidly dividing cells are the most radiosensitive, not resistant (A). The gastrointestinal (GI) mucosa is a rapidly renewing tissue and is therefore highly radiosensitive, not radioresistant (B). Small blood vessels contain sensitive endothelial cells, making them quite susceptible to radiation damage, not least resistant (D).",
